import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 1 Homework","description":"","frontmatter":{"source":"weeks/01-hello-vibe-coding/homework.md"},"headers":[],"relativePath":"weeks/01-hello-vibe-coding/homework.md","filePath":"weeks/01-hello-vibe-coding/homework.md"}'),s={name:"weeks/01-hello-vibe-coding/homework.md"};function r(i,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="week-1-homework" tabindex="-1">Week 1 Homework <a class="header-anchor" href="#week-1-homework" aria-label="Permalink to &quot;Week 1 Homework&quot;">​</a></h1><blockquote><p><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before). <strong>Core:</strong> about 5 hours including project time, required. <strong>Stretch:</strong> optional. Graded on effort and completion of the core tier (<a href="./../../assessment/rubrics.html#weekly-labs-and-homework">rubric</a>). &quot;On Canvas&quot; means the course&#39;s learning management system, not Gemini&#39;s Canvas tool.</p></blockquote><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><ul><li>☐ My <code>index.html</code> has at least three sections, at least five customization prompts behind it, and opens from my computer (task 1).</li><li>☐ It includes one small feature I wrote entirely by hand (🔴 AI off), and the latest version is uploaded to Canvas as &quot;Week 1 page&quot; (task 2).</li><li>☐ My scratch note lists the prompts that mattered and every change I made by hand (tasks 1–2). Next week it becomes <code>PROMPTS.md</code>.</li><li>☐ I worked through the first half of the AI Fluency course (task 3). The response is due in week 2.</li><li>☐ On Canvas: the signed <strong>safety contract</strong> and my <strong>pre-course self-assessment</strong>; my <strong>GitHub Education</strong> application is sent (task 4).</li><li>☐ On Canvas: my <strong>weekly reflection</strong> (🔴 AI off) (task 5).</li></ul><h2 id="time-plan" tabindex="-1">Time plan <a class="header-anchor" href="#time-plan" aria-label="Permalink to &quot;Time plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Kind</th><th>Time</th></tr></thead><tbody><tr><td>1. Finish your page</td><td>Project time</td><td>1 h 30 min</td></tr><tr><td>2. Write one feature by hand</td><td>Project time</td><td>30 min</td></tr><tr><td>3. AI fluency pre-work, part 1</td><td>Homework</td><td>1 h 30 min</td></tr><tr><td>4. Week 0 tasks for week 1</td><td>Homework</td><td>40 min</td></tr><tr><td>5. Weekly reflection</td><td>Journal</td><td>30 min</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>about 4 h 40 min</strong></td></tr></tbody></table><p>Before next week&#39;s Studio A, also read the <a href="./../02-ship-your-page/">week 2 page</a> (prep, up to 30 minutes).</p><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><h3 id="1-finish-your-page-1-h-30-min" tabindex="-1">1. Finish your page (1 h 30 min) <a class="header-anchor" href="#1-finish-your-page-1-h-30-min" aria-label="Permalink to &quot;1. Finish your page (1 h 30 min)&quot;">​</a></h3><p>🟢 AI on.</p><ol><li><strong>Start from your current file.</strong> Open a new chat and paste your saved <code>index.html</code> first, with a line such as &quot;Here is my current page. I changed some parts by hand; keep them.&quot; The AI can&#39;t see your hand changes otherwise.</li><li><strong>Reach at least five customization prompts</strong> in total, counting the ones from Studio A. One change per prompt; predict before you look; check against your &quot;Done when&quot;. Ideas: <a href="./prompt-starters.html#customization-prompts">customization prompts</a>.</li><li><strong>Have at least three sections</strong>, for example &quot;About me&quot;, &quot;Things I&#39;m learning&quot; and one of your choice (nothing personal). Next week you add a fourth, &quot;Projects&quot;.</li><li><strong>Check it at phone size:</strong> drag your browser window narrow. Nothing should stick out sideways.</li><li><strong>Save as you go.</strong> After each change that works, save <code>index.html</code>. Before a risky change, keep a copy of the last good version (for example <code>index-good.html</code>). That&#39;s a save point by hand; in week 3, git does this for you.</li><li>Log each prompt that mattered in your scratch note: the prompt, what happened, what you checked.</li></ol><p>✅ <strong>Checkpoint:</strong> <code>index.html</code> opens from your computer with at least three sections, and your scratch note lists at least five customization prompts.</p><h3 id="2-write-one-feature-by-hand-30-min" tabindex="-1">2. Write one feature by hand (30 min) <a class="header-anchor" href="#2-write-one-feature-by-hand-30-min" aria-label="Permalink to &quot;2. Write one feature by hand (30 min)&quot;">​</a></h3><p>🔴 AI off. You may use your own file, the <a href="./../../setup/python-to-javascript.html">bridge page</a> and <a href="https://developer.mozilla.org/en-US/docs/Web" target="_blank" rel="noreferrer">MDN</a>.</p><p>Add a <strong>second button</strong> that does something different from the first, written entirely by you. Pick one:</p><ul><li>it switches the page between two color themes;</li><li>it shows or hides one of your sections;</li><li>it counts how many times it has been clicked, and shows the number.</li></ul><p>You write all three parts: the <code>&lt;button&gt;</code> in the HTML, at least one CSS rule for it, and the JavaScript that finds it and listens for a click. Your existing fun-fact button is a working model: read how it does each part, then write your own. Predict, save, refresh, check.</p><p>Stuck after 20 minutes? Write down exactly where (which part, what you expected, what happened) in your scratch note and stop: that counts. If you need a hint, the JavaScript has this shape:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> myButton</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getElementById</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[your button&#39;s id]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">myButton.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addEventListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;click&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // change something on the page here</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Then upload the latest <code>index.html</code> to Canvas as &quot;Week 1 page&quot; (it replaces the Studio B upload), and add the feature to your scratch note&#39;s list of hand changes.</p><p>✅ <strong>Checkpoint:</strong> clicking your new button does what you planned, the fun-fact button still works, and Canvas has the latest file.</p><h3 id="3-ai-fluency-pre-work-part-1-1-h-30-min" tabindex="-1">3. AI fluency pre-work, part 1 (1 h 30 min) <a class="header-anchor" href="#3-ai-fluency-pre-work-part-1-1-h-30-min" aria-label="Permalink to &quot;3. AI fluency pre-work, part 1 (1 h 30 min)&quot;">​</a></h3><p>🟢 AI on for the course&#39;s own exercises.</p><p><strong>What:</strong> Anthropic&#39;s free online course <strong><a href="https://academy.claude.com/courses/ai-fluency-framework-foundations" target="_blank" rel="noreferrer">AI Fluency: Framework and foundations</a></strong>, or an equivalent your instructor names. It is about working well with <em>any</em> AI tool, not only Anthropic&#39;s. It names four skills: <strong>Delegation</strong> (deciding what to hand to an AI), <strong>Description</strong> (telling it clearly what you want), <strong>Discernment</strong> (judging what comes back) and <strong>Diligence</strong> (taking responsibility for what you do with it). It&#39;s also in the <a href="./../../resources/reading-list.html">Reading List</a>.</p><ol><li>Open the course and click <strong>Start course</strong>. You don&#39;t need an account to start; signing in only saves your progress, and you don&#39;t need a Claude account at all.</li><li>This week, work from the start through the lessons on <strong>Delegation</strong> (about 1½ hours). If the lesson list has changed, stop at about the halfway point. Week 2 covers the rest and a short response.</li><li>As you go, jot down one moment from building your page that fits a lesson. You&#39;ll use these notes in next week&#39;s response.</li></ol><h3 id="4-week-0-tasks-for-week-1-40-min" tabindex="-1">4. Week 0 tasks for week 1 (40 min) <a class="header-anchor" href="#4-week-0-tasks-for-week-1-40-min" aria-label="Permalink to &quot;4. Week 0 tasks for week 1 (40 min)&quot;">​</a></h3><p>These are in the &quot;During week 1&quot; section of the <a href="./../../setup/">week 0 pre-work</a>; the details are there.</p><ul><li><strong>Sign the <a href="./../../setup/safety-contract.html">safety contract</a> on Canvas</strong> (15 min). Read each rule and its plain-English summary. You sign on Canvas, not in a repository.</li><li><strong>Take the <a href="./../../assessment/self-assessment.html">pre-course self-assessment</a> on Canvas</strong> (15 min, 🔴 AI off). There are no wrong answers. You&#39;ll take it again at the end of the course to see how far you came.</li><li><strong>Apply for GitHub Education</strong> (10 min). Approval can take a few days, so apply now.</li></ul><h3 id="5-weekly-reflection-30-min" tabindex="-1">5. Weekly reflection (30 min) <a class="header-anchor" href="#5-weekly-reflection-30-min" aria-label="Permalink to &quot;5. Weekly reflection (30 min)&quot;">​</a></h3><p>🔴 AI off.</p><p>Answer questions 1–4 of the <a href="./../../templates/REFLECTION.html">reflection template</a> in 150–300 words, <strong>in your own words, without AI</strong>. Name specific moments: a prompt, a surprise in the preview, a line you changed. This week, also answer: <strong>which part of your page did the AI&#39;s tour explain well, and which part did you only understand once you changed it yourself?</strong> Submit it on <strong>Canvas</strong>, not in a repository: reflections are personal writing (<a href="./../../assessment/#privacy-of-your-work">Privacy of your work</a>).</p><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><h3 id="same-prompt-second-assistant" tabindex="-1">Same prompt, second assistant <a class="header-anchor" href="#same-prompt-second-assistant" aria-label="Permalink to &quot;Same prompt, second assistant&quot;">​</a></h3><p>Send your first prompt from the lab, unchanged, to a second assistant from the <a href="./../../TOOLS.html">Tool Handout</a>. Compare the two results in your scratch note:</p><table tabindex="0"><thead><tr><th>Question</th><th>Assistant 1</th><th>Assistant 2</th></tr></thead><tbody><tr><td>Did it meet every &quot;Done when&quot; item?</td><td></td><td></td></tr><tr><td>What did it add that you didn&#39;t ask for?</td><td></td><td></td></tr><tr><td>Roughly how many lines of code?</td><td></td><td></td></tr><tr><td>Which would you rather change by hand? Why?</td><td></td><td></td></tr></tbody></table><h3 id="a-fun-fact-button-that-never-repeats" tabindex="-1">A fun-fact button that never repeats <a class="header-anchor" href="#a-fun-fact-button-that-never-repeats" aria-label="Permalink to &quot;A fun-fact button that never repeats&quot;">​</a></h3><p>🔴 AI off. Change the fun-fact button so it never shows the same fact twice in a row. You&#39;ll need to remember the last fact shown and pick again while the new one matches it. Test it by clicking twenty times.</p><hr><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> your <code>index.html</code> opens in your browser and contains at least one change you made by hand. Week 2&#39;s Studio A publishes it, so bring it on your laptop (or download it from Canvas). If you have no working file, ask your instructor for the starter page before Studio A.</p></div>`,39)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
